    def list_transactions(
        self,
        account_id: str,
        *,
        date_from: str | _dt.date | NotGiven = NOT_GIVEN,
        date_to: str | _dt.date | NotGiven = NOT_GIVEN,
        status: Literal["booked", "pending"] | str | NotGiven = NOT_GIVEN,
        limit: int | NotGiven = NOT_GIVEN,
        page_token: str | NotGiven = NOT_GIVEN,
        extra_headers: Headers | None = None,
        extra_query: Query | None = None,
        extra_body: Body | None = None,
        timeout: float | httpx.Timeout | None | NotGiven = NOT_GIVEN,
    ) -> BankTransactionPage:
        """List account transactions.

        Date-range read of an account's transactions, sorted by `effective_date` descending, then `id` descending, in pages of up to 500. `date_from` and `date_to` are calendar dates, inclusive, in the bank's own time zone with nothing converted. They apply to `effective_date`: for a booked transaction its booking date, else its value date, else the date it was first seen; for a pending one its transaction date, else the date it was first seen. By default `date_from` is the start of the stored history and `date_to` has no upper bound, and booked and pending are both returned.

        The first page pins which transactions are included and each is served in its current state: a transaction removed while you page drops out of later pages and is reported by the change feed (`sync_transactions`). `page_token` continues one read and lives one hour; an expired token answers `410 page_expired`, so restart the read from its original query. To keep a copy up to date, use the change feed instead of re-reading ranges.

        Response headers: `X-Bank-Last-Synced-At` and `Cache-Control: no-store`.

        Needs an API key with the Bank data permission (`bank-data`): read for this operation. A key with full access does not include it: grant it explicitly when you create the key, or the call answers `403 bank_data_access_denied`. A sandbox application reads its Test Bank data with the key alone. A request without an API key (client credentials) is refused on raw data with the same `403`.

        ``GET /v3/bank/accounts/{account_id}/transactions/``

        Args:
          account_id: The account id.
          date_from: First effective date to include, inclusive.
          date_to: Last effective date to include, inclusive. No upper bound when you leave it out.
          status: Only booked or only pending transactions. Default both.
          limit: Page size, 1 to 500. Default 100.
          page_token: The `next_page_token` of the previous page.
          extra_headers: Headers to add to (or, with ``None``, remove from) this request.
          extra_query: Query parameters to add to this request.
          extra_body: Top-level JSON fields to add to this request's body.
          timeout: Overrides the client's timeout for this request, in seconds.
        """
        return cast(
            "BankTransactionPage",
            self._client.request(
                "get",
                "/v3/bank/accounts/{account_id}/transactions/",
                cast_to=BankTransactionPage,
                path_params={"account_id": account_id},
                auth="api_key",
                query={
                    "date_from": date_from,
                    "date_to": date_to,
                    "status": status,
                    "limit": limit,
                    "page_token": page_token,
                },
                extra_headers=extra_headers,
                extra_query=extra_query,
                extra_body=extra_body,
                timeout=timeout,
            ),
        )

    def sync_transactions(
        self,
        id: str,
        *,
        cursor: str | NotGiven = NOT_GIVEN,
        limit: int | NotGiven = NOT_GIVEN,
        page_token: str | NotGiven = NOT_GIVEN,
        extra_headers: Headers | None = None,
        extra_query: Query | None = None,
        extra_body: Body | None = None,
        timeout: float | httpx.Timeout | None | NotGiven = NOT_GIVEN,
    ) -> BankTransactionChanges:
        """Sync transactions (change feed).

        Returns what changed in a connection's transactions since a `cursor`: `added`, `modified` and `removed` (with a `reason`), across all its accounts. An empty cursor returns every current transaction as `added` and sets `reset: true`: replace your copy with it instead of adding to it.

        The first read is a true snapshot. A first read (no cursor, or the read after `reset`) returns every transaction the connection had when the read started, each exactly once as `added`, in its current state, even if a sync runs while you page. Changes made while you were paging arrive in the next read from `next_cursor`: a transaction you already received comes again as `modified`, and a new one as `added`. Apply `modified` as an upsert by `id`, and ignore a `removed` id you do not have. All pages of one read reflect the same point in time. Keep paging with `page_token` while `has_more` is `true`, and store `next_cursor` only after a response with `has_more: false`. If paging fails midway, restart from the cursor you had stored.

        The change log is replayable for 90 days. An older cursor answers `410 cursor_expired` with `bootstrap: true`: start again from an empty cursor. Stored history is never aged out while the connection exists. A booked pending transaction appears in `added` and the pending one in `removed` with `reason: pending_booked`. Webhook `bank.data.updated` tells you when to call.

        Needs an API key with the Bank data permission (`bank-data`): read for this operation. A key with full access does not include it: grant it explicitly when you create the key, or the call answers `403 bank_data_access_denied`. A sandbox application reads its Test Bank data with the key alone. A request without an API key (client credentials) is refused on raw data with the same `403`.

        ``GET /v3/bank/connections/{id}/transactions/sync/``

        Args:
          id: The connection id.
          cursor: The `next_cursor` you stored. Empty or omitted starts from the beginning.
          limit: Page size, 1 to 500. Default 100.
          page_token: Continues the same read while `has_more` is `true`.
          extra_headers: Headers to add to (or, with ``None``, remove from) this request.
          extra_query: Query parameters to add to this request.
          extra_body: Top-level JSON fields to add to this request's body.
          timeout: Overrides the client's timeout for this request, in seconds.
        """
        return cast(
            "BankTransactionChanges",
            self._client.request(
                "get",
                "/v3/bank/connections/{id}/transactions/sync/",
                cast_to=BankTransactionChanges,
                path_params={"id": id},
                auth="api_key",
                query={"cursor": cursor, "limit": limit, "page_token": page_token},
                extra_headers=extra_headers,
                extra_query=extra_query,
                extra_body=extra_body,
                timeout=timeout,
            ),
        )

