    async def sync_transactions(
        self,
        id: str,
        *,
        cursor: str | NotGiven = NOT_GIVEN,
        limit: int | NotGiven = NOT_GIVEN,
        page_token: str | NotGiven = NOT_GIVEN,
        extra_headers: Headers | None = None,
        extra_query: Query | None = None,
        extra_body: Body | None = None,
        timeout: float | httpx.Timeout | None | NotGiven = NOT_GIVEN,
    ) -> BankTransactionChanges:
        """Sync transactions (change feed).

        Returns what changed in a connection's transactions since a `cursor`: `added`, `modified` and `removed` (with a `reason`), across all its accounts. An empty cursor returns every current transaction as `added` and sets `reset: true`: replace your copy with it instead of adding to it.

        The first read is a true snapshot. A first read (no cursor, or the read after `reset`) returns every transaction the connection had when the read started, each exactly once as `added`, in its current state, even if a sync runs while you page. Changes made while you were paging arrive in the next read from `next_cursor`: a transaction you already received comes again as `modified`, and a new one as `added`. Apply `modified` as an upsert by `id`, and ignore a `removed` id you do not have. All pages of one read reflect the same point in time. Keep paging with `page_token` while `has_more` is `true`, and store `next_cursor` only after a response with `has_more: false`. If paging fails midway, restart from the cursor you had stored.

        The change log is replayable for 90 days. An older cursor answers `410 cursor_expired` with `bootstrap: true`: start again from an empty cursor. Stored history is never aged out while the connection exists. A booked pending transaction appears in `added` and the pending one in `removed` with `reason: pending_booked`. Webhook `bank.data.updated` tells you when to call.

        Needs an API key with the Bank data permission (`bank-data`): read for this operation. A key with full access does not include it: grant it explicitly when you create the key, or the call answers `403 bank_data_access_denied`. A sandbox application reads its Test Bank data with the key alone. A request without an API key (client credentials) is refused on raw data with the same `403`.

        ``GET /v3/bank/connections/{id}/transactions/sync/``

        Args:
          id: The connection id.
          cursor: The `next_cursor` you stored. Empty or omitted starts from the beginning.
          limit: Page size, 1 to 500. Default 100.
          page_token: Continues the same read while `has_more` is `true`.
          extra_headers: Headers to add to (or, with ``None``, remove from) this request.
          extra_query: Query parameters to add to this request.
          extra_body: Top-level JSON fields to add to this request's body.
          timeout: Overrides the client's timeout for this request, in seconds.
        """
        return cast(
            "BankTransactionChanges",
            await self._client.request(
                "get",
                "/v3/bank/connections/{id}/transactions/sync/",
                cast_to=BankTransactionChanges,
                path_params={"id": id},
                auth="api_key",
                query={"cursor": cursor, "limit": limit, "page_token": page_token},
                extra_headers=extra_headers,
                extra_query=extra_query,
                extra_body=extra_body,
                timeout=timeout,
            ),
        )

    async def list_institutions(
        self,
        *,
        country: str | NotGiven = NOT_GIVEN,
        segment: Literal["personal", "business"] | str | NotGiven = NOT_GIVEN,
        access: Literal["one_time", "ongoing"] | str | NotGiven = NOT_GIVEN,
        q: str | NotGiven = NOT_GIVEN,
        limit: int | NotGiven = NOT_GIVEN,
        cursor: str | NotGiven = NOT_GIVEN,
        extra_headers: Headers | None = None,
        extra_query: Query | None = None,
        extra_body: Body | None = None,
        timeout: float | httpx.Timeout | None | NotGiven = NOT_GIVEN,
    ) -> BankInstitutionList:
        """List institutions.

        Lists the banks per country with their capabilities: segments, access modes, the longest consent and deepest history the bank offers, whether it reports pending transactions, which transaction fields it is known to send, and how the person signs in. Values come from observed data, refreshed daily; a value never observed is `null`. The same data feeds the bank picker, so use it to know what to expect before you create a link. `access` lists `ongoing` only where ongoing access is available.

        Needs an API key with the Bank data permission (`bank-data`): read for this operation. A key with full access does not include it: grant it explicitly when you create the key, or the call answers `403 bank_data_access_denied`.

        The list is sorted by name, then id.

        In a sandbox application the list holds the Didit Test Bank, one per country Bank Link serves, and no live bank.

        ``GET /v3/bank/institutions/``

        Args:
          country: Only banks in this country, an ISO 3166-1 alpha-3 code. A country Bank Link does not serve answers `400 invalid_request` with `field: country`.
          segment: Only banks that serve this segment.
          access: Only banks that offer this access mode.
          q: Search by name or id, case-insensitive.
          limit: Page size, 1 to 500. Default 100.
          cursor: Opaque cursor from the previous page's `next_cursor`.
          extra_headers: Headers to add to (or, with ``None``, remove from) this request.
          extra_query: Query parameters to add to this request.
          extra_body: Top-level JSON fields to add to this request's body.
          timeout: Overrides the client's timeout for this request, in seconds.
        """
        return cast(
            "BankInstitutionList",
            await self._client.request(
                "get",
                "/v3/bank/institutions/",
                cast_to=BankInstitutionList,
                auth="api_key",
                query={
                    "country": country,
                    "segment": segment,
                    "access": access,
                    "q": q,
                    "limit": limit,
                    "cursor": cursor,
                },
                extra_headers=extra_headers,
                extra_query=extra_query,
                extra_body=extra_body,
                timeout=timeout,
            ),
        )

    async def get_institution(
        self,
        id: str,
        *,
        extra_headers: Headers | None = None,
        extra_query: Query | None = None,
        extra_body: Body | None = None,
        timeout: float | httpx.Timeout | None | NotGiven = NOT_GIVEN,
    ) -> BankInstitution:
        """Get an institution.

        Returns one bank with its capabilities. The id is Didit's slug, as listed by `list_institutions`.

        Needs an API key with the Bank data permission (`bank-data`): read for this operation. A key with full access does not include it: grant it explicitly when you create the key, or the call answers `403 bank_data_access_denied`.

        ``GET /v3/bank/institutions/{id}/``

        Args:
          id: The institution id, for example `es-banco-norte`.
          extra_headers: Headers to add to (or, with ``None``, remove from) this request.
          extra_query: Query parameters to add to this request.
          extra_body: Top-level JSON fields to add to this request's body.
          timeout: Overrides the client's timeout for this request, in seconds.
        """
        return cast(
            "BankInstitution",
            await self._client.request(
                "get",
                "/v3/bank/institutions/{id}/",
                cast_to=BankInstitution,
                path_params={"id": id},
                auth="api_key",
                extra_headers=extra_headers,
                extra_query=extra_query,
                extra_body=extra_body,
                timeout=timeout,
            ),
        )

    async def get_coverage(
        self,
        *,
        extra_headers: Headers | None = None,
        extra_query: Query | None = None,
        extra_body: Body | None = None,
        timeout: float | httpx.Timeout | None | NotGiven = NOT_GIVEN,
    ) -> BankCoverage:
        """Get bank data coverage.

        Returns one entry per country: whether bank sign-in and the account check are available, and whether ongoing access is available, with how many banks offer it, the longest consent and deepest history any of them allows, and whether business accounts are supported. Ongoing access is counted only where a bank is switched on for it. Use it to decide which countries to offer; use `list_institutions` for a single bank.

        Needs an API key with the Bank data permission (`bank-data`): read for this operation. A key with full access does not include it: grant it explicitly when you create the key, or the call answers `403 bank_data_access_denied`.

        ``GET /v3/bank/coverage/``

        Args:
          extra_headers: Headers to add to (or, with ``None``, remove from) this request.
          extra_query: Query parameters to add to this request.
          extra_body: Top-level JSON fields to add to this request's body.
          timeout: Overrides the client's timeout for this request, in seconds.
        """
        return cast(
            "BankCoverage",
            await self._client.request(
                "get",
                "/v3/bank/coverage/",
                cast_to=BankCoverage,
                auth="api_key",
                extra_headers=extra_headers,
                extra_query=extra_query,
                extra_body=extra_body,
                timeout=timeout,
            ),
        )


